package za.ac.cput.service; import org.springframework.stereotype.Service; import za.ac.cput.domain.Role; import za.ac.cput.repository.RoleRepository; @Service public class RoleServiceImpl implements RoleService{private final RoleRepository repository; public RoleServiceImpl(RoleRepository repository){this.repository=repository;} public Role create(Role x){return repository.save(x);} public Role read(String id){return repository.findById(id).orElse(null);} public Role update(Role x){return repository.save(x);} public boolean delete(String id){if(repository.existsById(id)){repository.deleteById(id);return true;}return false;} public java.util.List<Role> findAll(){return repository.findAll();} }